#include <stdio.h>
#include <stdlib.h>

int load_file(const char *path) {
    int status = 1;
    FILE *file = fopen(path, "r");
    char *buffer = NULL;

    if (file == NULL) { perror("fopen"); goto cleanup; }
    buffer = malloc(4096);
    if (buffer == NULL) { perror("malloc"); goto cleanup; }

    status = 0;  // procesar file usando buffer

cleanup:
    free(buffer);
    if (file != NULL) fclose(file);
    return status;
}
